// Create an account (screens/CreateAccount.jsx): the key made in this browser (signer/local.js) and the new account's
// first events (net/new-account.js). Every key here is generated by the test.
import test from "node:test"
import assert from "node:assert/strict"
import { getPublicKey, verifyEvent } from "nostr-tools/pure"
import { decrypt as ncryptsecOpen } from "nostr-tools/nip49"
import { decode } from "nostr-tools/nip19"
import { bytesToHex } from "nostr-tools/utils"
import * as nip44 from "nostr-tools/nip44"
import { bech32 } from "@scure/base"
import { newKey, checkPassword, localSession, localSigner, unlockLocal, revealNsec, wellFormed, LOCKED, DAMAGED, WRONG_PASSWORD, CREATING } from "../src/signer/local.js"
import { insecure } from "../src/signer/keyring.js"
import { saveSession, loadSession, loadAccounts, rememberAccount } from "../src/session.js"
import { signerFor } from "../src/signer/index.js"
import { cryptoFor } from "../src/net/dms.js"
import { starterPacks, newAccountTemplates, signAll, publishNewAccount, profileContent, NEW_ACCOUNT_RELAYS } from "../src/net/new-account.js"

/** keyring.js's store, in memory: add never replaces. */
function memKeys() {
  const m = new Map()
  return { m, get: async n => m.get(n), add: async (n, k) => { if (m.has(n)) throw new Error("exists"); m.set(n, k) } }
}
function memStorage() {
  const m = new Map()
  return { m, getItem: k => m.get(k) ?? null, setItem: (k, v) => m.set(k, String(v)), removeItem: k => m.delete(k) }
}
const PW = "correct horse"

test("a new key: npub and nsec name the same key", () => {
  const k = newKey()
  assert.equal(decode(k.npub).data, k.pubkey)
  assert.deepEqual(decode(k.nsec).data, k.sk)
  assert.equal(getPublicKey(k.sk), k.pubkey)
  assert.notEqual(newKey().pubkey, k.pubkey)
})

test("the password: at least 8 characters, typed the same twice (KeyPasswordStep)", () => {
  assert.deepEqual(checkPassword("", ""), { ok: false, problem: "" })
  assert.equal(checkPassword("short", "short").problem, "Password must be at least 8 characters")
  assert.equal(checkPassword("longenough", "longenougx").problem, "Passwords do not match")
  assert.equal(checkPassword("longenough", "").problem, "")
  assert.equal(checkPassword("longenough", "longenough").ok, true)
})

test("the stored session never holds the secret key in the clear", async () => {
  const k = newKey()
  const ks = memKeys()
  const s = await localSession(k.sk, PW, { keyStore: ks, logn: 4 })
  assert.equal(s.method, "local")
  assert.equal(s.pubkey, k.pubkey)
  const stored = JSON.stringify(s)
  for (const secret of [bytesToHex(k.sk), k.nsec, PW]) assert.ok(!stored.includes(secret), "session leaks a secret")
  assert.match(s.ncryptsec, /^ncryptsec1/)
  assert.deepEqual(ncryptsecOpen(s.ncryptsec, PW), k.sk) // the password opens the portable copy
  const storage = memStorage()
  saveSession(s, storage)
  assert.deepEqual(loadSession(storage), s)
  assert.equal(loadAccounts(storage).length, 1)
  for (const v of storage.m.values()) for (const secret of [bytesToHex(k.sk), k.nsec, PW]) assert.ok(!v.includes(secret))
})

test("a short password is refused before anything is stored", async () => {
  const ks = memKeys()
  await assert.rejects(localSession(newKey().sk, "short", { keyStore: ks, logn: 4 }), /at least 8/)
  assert.equal(ks.m.size, 0)
})

test("the local signer signs as the account, and encrypts messages with its key", async () => {
  const k = newKey()
  const ks = memKeys()
  const s = await localSession(k.sk, PW, { keyStore: ks, logn: 4 })
  const signer = localSigner(s, { keyStore: ks })
  await signer.ready()
  const ev = await signer.signEvent({ kind: 1, created_at: 1700000000, tags: [], content: "hi" })
  assert.equal(ev.pubkey, k.pubkey)
  assert.ok(verifyEvent(ev))
  const peer = newKey()
  const ct = await signer.crypto.encrypt(peer.pubkey, "secret note")
  assert.equal(nip44.v2.decrypt(ct, nip44.v2.utils.getConversationKey(peer.sk, k.pubkey)), "secret note")
  assert.equal(await signer.crypto.decrypt(peer.pubkey, ct), "secret note")
  assert.equal(await signer.crypto.decrypt04(peer.pubkey, await signer.crypto.encrypt04(peer.pubkey, "old dm")), "old dm")
  assert.equal(cryptoFor(s, { signer }), signer.crypto) // Messages can use it
  assert.equal(signerFor(s).method, "local")
})

test("a lost sealing key locks the signer; the password unlocks it again, a wrong one doesn't", async () => {
  const k = newKey()
  const s = await localSession(k.sk, PW, { keyStore: memKeys(), logn: 4 })
  const fresh = memKeys() // the browser's sealing key is gone
  await assert.rejects(localSigner(s, { keyStore: fresh }).ready(), e => e.message === LOCKED)
  await assert.rejects(unlockLocal(s, "wrong password", { keyStore: fresh }), /Wrong password/)
  const unlocked = await unlockLocal(s, PW, { keyStore: fresh })
  assert.equal(unlocked.ncryptsec, s.ncryptsec)
  const ev = await localSigner(unlocked, { keyStore: fresh }).signEvent({ kind: 1, created_at: 1, tags: [], content: "" })
  assert.equal(ev.pubkey, k.pubkey)
})

test("the key is locked at NIP-49's logn 16 unless a test asks for less", async () => {
  const s = await localSession(newKey().sk, PW, { keyStore: memKeys() })
  const b = bech32.fromWords(bech32.decode(s.ncryptsec, 5000).words)
  assert.equal(b[0], 2)
  assert.equal(b[1], 16)
})

test("a missing or damaged ncryptsec says so; only a real one answers Wrong password", async () => {
  const k = newKey()
  const s = await localSession(k.sk, PW, { keyStore: memKeys(), logn: 4 })
  assert.equal(wellFormed(s.ncryptsec), true)
  const broken = [undefined, "", "ncryptsec1", s.ncryptsec.slice(0, -6), s.ncryptsec.slice(0, -1) + (s.ncryptsec.endsWith("q") ? "p" : "q")]
  for (const ncryptsec of broken) {
    assert.equal(wellFormed(ncryptsec), false, String(ncryptsec))
    await assert.rejects(unlockLocal({ ...s, ncryptsec }, PW, { keyStore: memKeys() }), e => e.message === DAMAGED)
  }
  // Another account's ncryptsec: the password opens it, but it isn't this account's key.
  const other = await localSession(newKey().sk, PW, { keyStore: memKeys(), logn: 4 })
  await assert.rejects(unlockLocal({ ...s, ncryptsec: other.ncryptsec }, PW, { keyStore: memKeys() }), e => e.message === DAMAGED)
  await assert.rejects(unlockLocal(s, "wrong password", { keyStore: memKeys() }), e => e.message === WRONG_PASSWORD)
  // A cost a tab can't run (logn 21 wants about 2 GiB) is damage too, not a password to keep retrying.
  const b = bech32.fromWords(bech32.decode(s.ncryptsec, 5000).words); b[1] = 21
  assert.equal(wellFormed(bech32.encode("ncryptsec", bech32.toWords(b), 5000)), false)
})

test("a local account without an ncryptsec isn't an account", () => {
  const storage = memStorage()
  assert.throws(() => rememberAccount({ method: "local", pubkey: newKey().pubkey }, storage), /not an account/)
  storage.setItem("nv-accounts", JSON.stringify([{ method: "local", pubkey: newKey().pubkey }]))
  assert.deepEqual(loadAccounts(storage), [])
})

test("Your Secret Key: the password shows the nsec, a wrong one doesn't", async () => {
  const k = newKey()
  const s = await localSession(k.sk, PW, { keyStore: memKeys(), logn: 4 })
  assert.equal(revealNsec(s, PW), k.nsec)
  assert.throws(() => revealNsec(s, "wrong password"), e => e.message === WRONG_PASSWORD)
  assert.throws(() => revealNsec({ ...s, ncryptsec: undefined }, PW), e => e.message === DAMAGED)
})

test("a plain-http page says Creating an account, not bunker", () => {
  assert.equal(insecure(CREATING), "Creating an account needs a secure page: open Nostr Vault over https (or on localhost), not plain http.")
})

test("starter packs: hex pubkeys, bad npubs dropped, Bitcoin starts unpicked and last", () => {
  const packs = starterPacks({ packs: [
    { id: "bitcoin", name: "Bitcoin", description: "", accounts: [{ npub: newKey().npub, name: "c" }] },
    { id: "nostr", name: "Nostr", description: "", accounts: [{ npub: newKey().npub, name: "a" }, { npub: "npub1bad", name: "b" }] },
    { id: "empty", name: "Empty", description: "", accounts: [{ npub: "nope" }] },
  ] })
  assert.deepEqual(packs.map(p => [p.id, p.on, p.accounts.length]), [["nostr", true, 1], ["bitcoin", false, 1]])
  assert.match(packs[0].accounts[0].pubkey, /^[0-9a-f]{64}$/)
  const real = starterPacks()
  assert.ok(real.length >= 3 && real.every(p => p.accounts.length > 0), "the bundled packs load")
})

test("first events: relay list, DM relays, profile only with something in it, follows only when picked", async () => {
  const people = [newKey().pubkey, newKey().pubkey]
  const kinds = t => t.map(e => e.kind)
  assert.deepEqual(kinds(newAccountTemplates({ name: "", picture: null, follows: [] })), [10002, 10050])
  const t = newAccountTemplates({ name: "  Ada ", picture: "https://blossom.example/x.jpg", follows: [...people, people[0], "junk"], at: 5 })
  assert.deepEqual(kinds(t), [10002, 10050, 0, 3])
  assert.deepEqual(JSON.parse(t[2].content), { name: "Ada", display_name: "Ada", picture: "https://blossom.example/x.jpg" })
  assert.deepEqual(t[3].tags, people.map(pk => ["p", pk]))
  assert.deepEqual(t[0].tags, NEW_ACCOUNT_RELAYS.map(r => ["r", r]))
  assert.ok(NEW_ACCOUNT_RELAYS.every(r => r.startsWith("wss://")))
  assert.ok(t[1].tags.length > 0 && t[1].tags.every(x => x[0] === "relay"))
  assert.equal(profileContent(" ", null), null)

  const k = newKey()
  const ks = memKeys()
  const s = await localSession(k.sk, PW, { keyStore: ks, logn: 4 })
  const events = await signAll(localSigner(s, { keyStore: ks }), s.pubkey, t)
  assert.ok(events.every(e => e.pubkey === k.pubkey && verifyEvent(e)))
  const sent = []
  const res = await publishNewAccount(events, { publish: (urls, ev) => { sent.push([urls, ev.kind]); return urls.map(() => Promise.resolve("ok")) } })
  assert.deepEqual(res.map(r => r.kind), [10002, 10050, 0, 3])
  assert.ok(sent.every(([urls]) => urls.length > 0 && urls.every(u => /^wss:\/\//.test(u))))
})

test("the first events count as sent at the first relay's OK, not the slowest relay's answer", async () => {
  const k = newKey()
  const ks = memKeys()
  const s = await localSession(k.sk, PW, { keyStore: ks, logn: 4 })
  const events = await signAll(localSigner(s, { keyStore: ks }), s.pubkey, newAccountTemplates({ name: "Ada", picture: null, follows: [] }))
  let release
  const slow = new Promise(r => { release = r })
  // Each event: the first relay refuses, the second takes it, the rest have not answered.
  const publish = urls => urls.map((_, i) => i === 0 ? Promise.reject(new Error("blocked")) : i === 1 ? Promise.resolve("ok") : slow.then(() => "ok"))
  const res = await publishNewAccount(events, { publish })
  assert.deepEqual(res.map(r => r.taken), events.map(() => true))
  release()
  const counts = await Promise.all(res.map(r => r.settled))
  assert.deepEqual(counts, res.map(r => r.of - 1))

  const none = await publishNewAccount(events, { publish: urls => urls.map(() => Promise.reject(new Error("down"))) })
  assert.deepEqual(none.map(r => r.taken), events.map(() => false))
})
